<script setup lang="ts">
import {ref} from 'vue'
import {NButton,NInput,NModal,NSelect} from 'naive-ui'
import type {StockAccount,Sku,Account,Transfer} from '../api/funds'
import {warehouse,today,type StockInput} from '../api/warehouse'
import StockAccountSelector from './StockAccountSelector.vue'
import EndpointSelector from './EndpointSelector.vue'
import TagInput from './TagInput.vue'
const props=defineProps<{locations:StockAccount[];skus:Sku[];accounts:Account[];funds:Transfer[];hideTrigger?:boolean;initial?:Partial<StockInput>}>()
const emit=defineEmits<{saved:[]}>()
const show=ref(false),busy=ref(false),error=ref(''),source=ref(''),destination=ref(''),date=ref(today()),description=ref(''),tags=ref<string[]>([]),reference=ref(''),related=ref(''),refs=ref<string[]>([]),lines=ref([{sku_id:'',quantity:''}])
const moneyMode=ref('none'),moneySource=ref(''),moneyDestination=ref(''),amount=ref('')
function open(initial:Partial<StockInput>=props.initial||{}){source.value=initial.source_account_id||'';destination.value=initial.destination_account_id||'';date.value=today();description.value=initial.description||'';tags.value=[...(initial.tags||[])];reference.value='';related.value=initial.related_transfer_id||'';refs.value=[];lines.value=initial.lines?.map(l=>({...l}))||[{sku_id:'',quantity:''}];moneyMode.value='none';moneySource.value='';moneyDestination.value='';amount.value='';error.value='';show.value=true}
defineExpose({open})
async function save(){if(busy.value)return;busy.value=true;error.value='';try{const stock:StockInput={source_account_id:source.value,destination_account_id:destination.value,effective_date:date.value,description:description.value,tags:tags.value,source_reference:reference.value||null,related_transfer_id:related.value||null,fund_transfer_ids:moneyMode.value==='none'?refs.value:[],lines:lines.value};if(moneyMode.value==='none')await warehouse.submit(stock);else await warehouse.operation({stock,money:{source_account_id:moneySource.value,destination_account_id:moneyDestination.value,amount:amount.value,effective_date:date.value,description:description.value,tags:tags.value,counterparty:null}});show.value=false;emit('saved')}catch(e){error.value=(e as Error).message+'。结果不确定时，请先查看记录。'}finally{busy.value=false}}
</script>
<template><NButton v-if="!hideTrigger" type="primary" @click="open()">新建货物转移</NButton><NModal v-model:show="show" preset="card" title="货物转移" class="dialog"><fieldset :disabled="busy"><StockAccountSelector v-model="source" :locations="locations" label="来源" :disabled="busy"/><StockAccountSelector v-model="destination" :locations="locations" label="去向" :disabled="busy"/><label>日期<input v-model="date" type="date"></label><label>说明<NInput v-model:value="description" type="textarea" :disabled="busy"/></label><label>标签<TagInput v-model="tags" :disabled="busy"/></label><label>原始单据编号<NInput v-model:value="reference" :disabled="busy"/></label><label>关联转移编号<NInput v-model:value="related" :disabled="busy" placeholder="可留空"/></label><div v-for="(line,i) in lines" :key="i" class="filters"><NSelect v-model:value="line.sku_id" :disabled="busy" :options="skus.filter(s=>s.active).map(s=>({label:`${s.name}（${s.unit}）`,value:s.id}))" placeholder="SKU"/><NInput v-model:value="line.quantity" :disabled="busy" placeholder="正整数数量"/><NButton :disabled="busy||lines.length===1" @click="lines.splice(i,1)">删除</NButton></div><NButton :disabled="busy" @click="lines.push({sku_id:'',quantity:''})">增加 SKU</NButton><label>资金关联<NSelect v-model:value="moneyMode" :disabled="busy" :options="[{label:'已有记录或不关联',value:'none'},{label:'同时新建资金转移',value:'new'}]"/></label><NSelect v-if="moneyMode==='none'" v-model:value="refs" :disabled="busy" multiple clearable :options="funds.map(f=>({label:`${f.description||f.id}（${f.status}）`,value:f.id}))" placeholder="选择已有资金记录"/><template v-else><p>资金按原规则审批过账，货物须另外确认完成。</p><EndpointSelector v-model="moneySource" :accounts="accounts" label="资金来源" :disabled="busy"/><EndpointSelector v-model="moneyDestination" :accounts="accounts" label="资金去向" :disabled="busy"/><label>金额（元）<NInput v-model:value="amount" :disabled="busy"/></label></template></fieldset><p class="error">{{error}}</p><NButton :loading="busy" @click="save">提交</NButton></NModal></template>
